function nextPortalNumber(){
 const year=new Date().getFullYear();
 const records=[...JSON.parse(localStorage.getItem('ascend_shipments')||'[]'),...JSON.parse(localStorage.getItem('ascend_ncts_records')||'[]')];
 const max=records.reduce((max,r)=>{const match=(r.fileNo||r.no||'').match(new RegExp('^ASC-'+year+'-(\\d+)$'));return match?Math.max(max,Number(match[1])):max;},0);
 const next=Math.max(max+1,Number(localStorage.getItem('ascend_counter')||1));
 localStorage.setItem('ascend_counter',String(next+1));return 'ASC-'+year+'-'+String(next).padStart(4,'0');
}

const portalCurrencies=['EUR','USD','TRY','GBP','CHF','JPY','CNY','AED','SAR','RUB','CAD','AUD','NZD','SEK','NOK','DKK','PLN','CZK','HUF','RON','BGN','INR','KRW','SGD','HKD','ZAR','BRL','MXN','KWD','QAR','BHD','OMR','EGP','AZN','GEL','KZT','UZS'];
function fillPortalSelect(input,values){
 const value=input.value,select=input.tagName==='SELECT'?input:document.createElement('select');
 if(select!==input){for(const attr of input.attributes){if(!['type','list','maxlength','placeholder'].includes(attr.name))select.setAttribute(attr.name,attr.value);}input.replaceWith(select);}
 select.replaceChildren();for(const v of ['',...values]){const option=document.createElement('option');option.value=v;option.textContent=v||'Seçiniz';select.append(option);}select.value=values.includes(value)?value:'';return select;
}
window.addEventListener('DOMContentLoaded',()=>{
 for(const id of ['loadCurrency','eCurrency','fCurrency','accountCurrency','nValueCurrency','nctsFeeCurrency']){const input=document.getElementById(id);if(input)fillPortalSelect(input,portalCurrencies);}
 document.querySelectorAll('label').forEach(label=>{if(/Gümr/i.test(label.textContent)){const input=label.parentElement.querySelector('input');if(input)fillPortalSelect(input,officialCustoms);}});
});
